    context=[ex("Una exposición muestra dos fotos: una familia que cultiva en un oasis y otra que cría llamas en el altiplano. Ambas están en el norte. ¿Qué te dice eso sobre ambiente y decisión?", "Que en una misma zona se pueden hacer cosas distintas según el lugar y la decisión", "El ambiente da posibilidades y la comunidad elige.")],
    selfcheck=[ex("¿Qué es una receta?", "Pasos que siempre salen igual", "El ambiente no es una receta."), ex("¿Qué partes tiene una buena explicación?", "Ambiente, conocimiento y decisión", "Son las tres de la clase."), ex("¿Quién decide qué hacer con un recurso?", "La comunidad", "Usa su conocimiento y elige.")],
    open_task=task("Escribe una explicación de tres frases sobre una comunidad del altiplano. Usa esta ficha: ambiente = poca agua y frío; conocimiento = sabe criar llamas y tejer; decisión = criar llamas y tejer ropa de lana. Empieza cada frase con ambiente, conocimiento o decisión.", "El ambiente es el altiplano con poca agua y frío. El conocimiento es que sabe criar llamas y tejer. La decisión fue criar llamas y tejer ropa de lana.", ["usa las tres partes", "no dice que el lugar obliga", "es clara y completa"], ["tres frases"], ["olvidar el conocimiento", "decir que el ambiente decide todo"], "Pide a un adulto que busque las tres partes en tu texto."),
