    selfcheck=[ex("¿Qué es un proyecto de convivencia?", "Una acción para mejorar el trato", "Se practica varios días."), ex("¿Para qué sirve el registro?", "Para anotar si se cumplió", "Así se puede revisar."), ex("¿Qué se evalúa al final?", "Si la acción ayudó al grupo", "No se evalúa si las personas son buenas o malas.")],
